package com.nequard.rewards;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="nqd_ledger") public class NqdLedgerEntry{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)UUID userId;@Column(name="organization_id",nullable=false)UUID organizationId;@Column(nullable=false)Long amount;@Column(nullable=false)String type;String description;Instant createdAt=Instant.now();
public UUID getId(){return id;}public UUID getUserId(){return userId;}public void setUserId(UUID v){userId=v;}public UUID getOrganizationId(){return organizationId;}public void setOrganizationId(UUID v){organizationId=v;}public Long getAmount(){return amount;}public void setAmount(Long v){amount=v;}public String getType(){return type;}public void setType(String v){type=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public Instant getCreatedAt(){return createdAt;}}